// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 val, address actor) public {
        val = bound(val, 0, type(uint256).max - 1);
        vm.prank(actor);
        try c.SetMinSum(val) {
            assertEq(c.MinSum(), val, "MinSum must equal the value passed to SetMinSum");
        } catch {
            assertTrue(true);
        }
    }
}
